table inet fw4 {
	chain forward_trusted {
		jump accept_to_wan comment "!fw4: Accept trusted to wan forwarding"
		jump reject_to_trusted
	}
}
table inet fw4 {
	chain forward_guest {
		jump accept_to_wan comment "!fw4: Accept guest to wan forwarding"
		jump reject_to_guest
	}
}
table inet fw4 {
	chain accept_to_wan {
		meta nfproto ipv4 oifname "br-lan" ct state invalid counter packets 0 bytes 0 drop comment "!fw4: Prevent NAT leakage"
		oifname "br-lan" counter packets 44 bytes 3400 accept comment "!fw4: accept wan IPv4/IPv6 traffic"
	}
}
table inet fw4 {
	chain srcnat_wan {
		meta nfproto ipv4 masquerade comment "!fw4: Masquerade IPv4 wan traffic"
	}
}
